[
  {
    "title": "technique-hints-repeat-directions",
    "claim": "In Image #3, STANCE maps directions to actions such as step, jump, and crouch, whereas TECHNIQUE labels directions only as back, forward, up, and down.",
    "reason": "The player can learn movement from the hint but cannot identify which technique direction selects a punch or kick.",
    "suggest": "Show the current stance’s attack names beside the technique directions, using the same mappings displayed in the Techniques panel."
  },
  {
    "title": "technique-legend-delays-move-list",
    "claim": "In Image #6, five STANCE legend entries and four TECHNIQUE legend entries appear in vertically stacked sections before the first named attack.",
    "reason": "The reference prioritizes notation over the attacks a player opened it to find.",
    "suggest": "Arrange the two legends side by side, preserving readable text, and place the named attack groups immediately below the scoring explanation."
  },
  {
    "title": "keyboard-bindings-not-visible",
    "claim": "In Image #9, the visible STANCE and TECHNIQUE controls contain directional marks but no keyboard-key labels.",
    "reason": "A keyboard player cannot discover the corresponding keys from this screen.",
    "suggest": "Add the actual keyboard bindings beside their corresponding stance and technique directions in the desktop control area."
  },
  {
    "title": "briefing-shows-start-pressure",
    "claim": "In Image #2, the opponent briefing remains visible while the FIGHT card also displays STARTING IN 2.",
    "reason": "The countdown wording creates pressure to proceed while the player is reading, although this still cannot establish whether the bout actually starts automatically.",
    "suggest": "Make the briefing player-paced: display 'Tap FIGHT when ready' and reserve a countdown for after the player confirms."
  },
  {
    "title": "win-time-basis-unexplained",
    "claim": "In Image #18, the HUD displays 29s and the record badge displays FASTEST WIN 6.4S, but the frame cannot establish whether those figures use the same timing basis.",
    "reason": "The player has no explanation for how the remaining round time relates to the recorded win duration.",
    "suggest": "Capture both clocks’ start, pause, and stop timestamps for the same bout, then label the record as 'Elapsed win time' or 'Active fight time' according to its verified basis rather than assuming either calculation is wrong."
  }
]
